function glassCss(o){
  o=o||{};
  var blur=(+o.blur); if(isNaN(blur))blur=10;
  var alpha=(+o.alpha); if(isNaN(alpha))alpha=0.15;
  var r=(+o.radius); if(isNaN(r))r=16;
  var ba=(+o.border); if(isNaN(ba))ba=0.18;
  var tint=o.tint||'255,255,255';
  return 'background: rgba('+tint+', '+alpha.toFixed(2)+');\n'+
    'backdrop-filter: blur('+blur+'px);\n'+
    '-webkit-backdrop-filter: blur('+blur+'px);\n'+
    'border: 1px solid rgba('+tint+', '+ba.toFixed(2)+');\n'+
    'border-radius: '+r+'px;\n'+
    'box-shadow: 0 8px 32px rgba(0,0,0,0.25);';
}
var EXPORTS={glassCss:glassCss};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GlassmorphismForgePure = EXPORTS; }
